package ca.yorku.eecs3311.coursepilot.web;
import ca.yorku.eecs3311.coursepilot.application.StudyAgentFacade; import ca.yorku.eecs3311.coursepilot.application.service.StudyPlanService; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import java.time.LocalDate;
@Controller @RequestMapping("/courses/{courseId}/study-plan") public class StudyPlanController {private final StudyAgentFacade facade;private final StudyPlanService plans;public StudyPlanController(StudyAgentFacade f,StudyPlanService p){facade=f;plans=p;}@GetMapping public String page(@PathVariable Long courseId,Model m){m.addAttribute("course",facade.getCourse(courseId));m.addAttribute("plans",plans.list(courseId));m.addAttribute("activeNav","study-plan");return "study-plan/index";}@PostMapping public String create(@PathVariable Long courseId,@RequestParam LocalDate startDate,@RequestParam LocalDate targetDate,@RequestParam Integer minutes,@RequestParam String strategy,Model m){try{plans.create(courseId,startDate,targetDate,minutes,strategy);m.addAttribute("planMessage","Study plan created.");}catch(RuntimeException e){m.addAttribute("planError",e.getMessage());}return page(courseId,m);}}
